# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

The implemented plan is [`system-one-client.md`](system-one-client.md).

//! Public surface smoke tests.

#![allow(clippy::expect_used)]

use std::collections::BTreeMap;

use serde_json::json;
use tinyjevclient::{Choice, EvaluationRequest, Question};

#[test]
fn public_types_build_a_valid_jev_request() {
    let request = EvaluationRequest::jev(
        "route this",
        BTreeMap::from([(
            "route".to_owned(),
            Question::Choice(Choice {
                instructions: json!("Who should handle this?"),
                criteria: BTreeMap::from([
                    ("planner".to_owned(), None),
                    ("reviewer".to_owned(), None),
                ]),
            }),
        )]),
    );
    request.validate().expect("public request should validate");
}

//! Response wire and request-relative validation tests.

#![allow(clippy::unwrap_used, clippy::panic)]

use std::collections::BTreeMap;

use serde_json::json;

use super::*;
use crate::{Choice, EvaluationRequest, Noul, Question, Score};

fn request() -> EvaluationRequest {
    EvaluationRequest::jev(
        "state",
        BTreeMap::from([
            (
                "route".to_owned(),
                Question::Choice(Choice {
                    instructions: json!("route"),
                    criteria: BTreeMap::from([("a".to_owned(), None), ("b".to_owned(), None)]),
                }),
            ),
            (
                "quality".to_owned(),
                Question::Score(Score {
                    instructions: json!("quality"),
                    criteria: vec![json!("low"), json!("high")],
                }),
            ),
            (
                "safe".to_owned(),
                Question::Noul(Noul {
                    instructions: json!("safe"),
                    criteria: None,
                }),
            ),
        ]),
    )
}

fn response() -> EvaluationResponse {
    serde_json::from_value(json!({
        "model": "jev-latest",
        "answers": {
            "route": {
                "type": "choice",
                "choice": "b",
                "probabilities": {"a": 0.25, "b": 0.75},
                "confidence": 0.5
            },
            "quality": {
                "type": "score",
                "score": 0.8,
                "legend": {"0": "low", "1": "high"},
                "probabilities": {"0": 0.2, "1": 0.8},
                "confidence": 0.6
            },
            "safe": {"type": "noul", "noul": 0.9}
        },
        "usage": {"input_tokens": 42, "output_tokens": 3}
    }))
    .unwrap()
}

#[test]
fn validates_all_three_answer_types() {
    response().validate_for(&request()).unwrap();
    let mut rounded = response();
    let Answer::Score(answer) = rounded.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    answer.score = 0.81;
    rounded.validate_for(&request()).unwrap();
}

#[test]
fn usage_fields_remain_optional() {
    let usage: Usage = serde_json::from_value(json!({})).unwrap();
    assert_eq!(usage, Usage::default());
}

#[test]
fn rejects_missing_extra_or_wrongly_typed_answers() {
    let mut missing = response();
    missing.answers.remove("safe");
    assert!(missing.validate_for(&request()).is_err());

    let mut wrong = response();
    wrong.answers.insert(
        "safe".to_owned(),
        Answer::Choice(ChoiceAnswer {
            choice: "a".to_owned(),
            probabilities: BTreeMap::from([("a".to_owned(), 1.0)]),
            confidence: 1.0,
        }),
    );
    assert!(wrong.validate_for(&request()).is_err());
}

#[test]
fn rejects_invalid_distributions_and_inconsistent_scores() {
    let mut distribution = response();
    let Answer::Choice(choice) = distribution.answers.get_mut("route").unwrap() else {
        panic!("fixture answer should be a choice")
    };
    choice.probabilities.insert("a".to_owned(), 0.75);
    assert!(distribution.validate_for(&request()).is_err());

    let mut score = response();
    let Answer::Score(answer) = score.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    answer.score = 0.1;
    assert!(score.validate_for(&request()).is_err());
}

#[test]
fn rejects_empty_model_extra_ids_and_nonmaximal_choice() {
    let mut empty_model = response();
    empty_model.model.clear();
    assert!(empty_model.validate_for(&request()).is_err());

    let mut wrong_model = response();
    wrong_model.model = "jev-other".into();
    assert!(wrong_model.validate_for(&request()).is_err());

    let mut extra = response();
    extra
        .answers
        .insert("extra".into(), Answer::Noul(NoulAnswer { noul: 0.5 }));
    assert!(extra.validate_for(&request()).is_err());

    let mut nonmaximal = response();
    let Answer::Choice(choice) = nonmaximal.answers.get_mut("route").unwrap() else {
        panic!("fixture answer should be a choice")
    };
    choice.choice = "a".into();
    assert!(nonmaximal.validate_for(&request()).is_err());
}

#[test]
fn openrouter_accepts_resolved_jev_models_only() {
    let mut resolved = response();
    resolved.model = "typesafe/jev-1.13-20260917".into();
    resolved.validate_for_openrouter(&request()).unwrap();

    let mut namespaced_latest = request();
    namespaced_latest.model = "~typesafe/jev-latest".into();
    resolved
        .validate_for_openrouter(&namespaced_latest)
        .unwrap();

    let mut unrelated = resolved;
    unrelated.model = "typesafe/other-1".into();
    assert!(unrelated.validate_for_openrouter(&request()).is_err());
}

#[test]
fn rejects_out_of_range_empty_and_mismatched_probability_payloads() {
    let mut confidence = response();
    let Answer::Choice(choice) = confidence.answers.get_mut("route").unwrap() else {
        panic!("fixture answer should be a choice")
    };
    choice.confidence = 1.1;
    assert!(confidence.validate_for(&request()).is_err());

    let mut empty = response();
    let Answer::Choice(choice) = empty.answers.get_mut("route").unwrap() else {
        panic!("fixture answer should be a choice")
    };
    choice.probabilities.clear();
    assert!(empty.validate_for(&request()).is_err());

    let mut labels = response();
    let Answer::Choice(choice) = labels.answers.get_mut("route").unwrap() else {
        panic!("fixture answer should be a choice")
    };
    choice.probabilities.remove("a");
    choice.probabilities.insert("c".into(), 0.25);
    assert!(labels.validate_for(&request()).is_err());

    let mut noul = response();
    let Answer::Noul(answer) = noul.answers.get_mut("safe").unwrap() else {
        panic!("fixture answer should be a noul")
    };
    answer.noul = f64::NAN;
    assert!(noul.validate_for(&request()).is_err());
}

#[test]
fn rejects_nonfinite_score_and_mismatched_legend() {
    let mut nonfinite = response();
    let Answer::Score(score) = nonfinite.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    score.score = f64::INFINITY;
    assert!(nonfinite.validate_for(&request()).is_err());

    let mut outside = response();
    let Answer::Score(score) = outside.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    score.probabilities = BTreeMap::from([("0".into(), 0.98), ("1".into(), 0.02)]);
    score.score = -0.01;
    assert!(outside.validate_for(&request()).is_err());

    let mut legend = response();
    let Answer::Score(score) = legend.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    score.legend.remove("1");
    assert!(legend.validate_for(&request()).is_err());

    let mut reversed = response();
    let Answer::Score(score) = reversed.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    score.legend.insert("0".into(), json!("high"));
    score.legend.insert("1".into(), json!("low"));
    assert!(reversed.validate_for(&request()).is_err());
}

#[test]
fn accepts_the_exact_score_rounding_boundary() {
    let mut boundary = response();
    let Answer::Score(score) = boundary.answers.get_mut("quality").unwrap() else {
        panic!("fixture answer should be a score")
    };
    score.probabilities = BTreeMap::from([("0".into(), 0.97), ("1".into(), 0.03)]);
    score.score = 0.05;
    boundary.validate_for(&request()).unwrap();
}

#[test]
fn many_option_distributions_tolerate_per_option_rounding() {
    // 21 options rounded to two decimals summing to 0.99: what the OpenRouter
    // endpoint answers. Rejected before the size-aware tolerance.
    let mut probabilities = std::collections::BTreeMap::new();
    for i in 0..20 {
        probabilities.insert(format!("o{i}"), 0.04);
    }
    probabilities.insert("o20".to_owned(), 0.19);
    assert!((probabilities.values().sum::<f64>() - 0.99).abs() < 1e-9);
    assert!(validate_distribution(&probabilities, "choice").is_ok());

    // Two options are still held tightly.
    let two = std::collections::BTreeMap::from([("a".to_owned(), 0.6), ("b".to_owned(), 0.39)]);
    assert!(validate_distribution(&two, "choice").is_err());
}

//! Error rendering behavior.

use super::*;

#[test]
fn messages_do_not_render_secrets_or_response_bodies() {
    let errors = [
        Error::MissingApiKey,
        Error::Authentication,
        Error::Unprocessable,
        Error::RateLimited,
        Error::Overloaded,
        Error::HttpStatus { status: 503 },
        Error::Timeout,
    ];
    for error in errors {
        let rendered = error.to_string();
        assert!(!rendered.contains("Bearer"));
        assert!(!rendered.contains("apikey_"));
    }
}

#[test]
fn contextual_errors_name_their_category() {
    assert_eq!(
        Error::invalid_request("questions must not be empty").to_string(),
        "invalid request: questions must not be empty"
    );
    assert_eq!(
        Error::invalid_response("answer missing").to_string(),
        "invalid response: answer missing"
    );
}

//! Client transport, retry, measurement, and secret-handling tests.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::{
    collections::BTreeMap,
    sync::Arc,
    time::{Duration, SystemTime},
};

use serde_json::json;
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::TcpListener,
    sync::Mutex,
};

use super::*;
use crate::{Choice, Question};

fn request() -> EvaluationRequest {
    EvaluationRequest::jev(
        json!({"message": "review this"}),
        BTreeMap::from([(
            "route".to_owned(),
            Question::Choice(Choice {
                instructions: json!("Who should answer?"),
                criteria: BTreeMap::from([("alice".to_owned(), None), ("bob".to_owned(), None)]),
            }),
        )]),
    )
}

fn success() -> String {
    json!({
        "model": "jev-latest",
        "answers": {
            "route": {
                "type": "choice",
                "choice": "bob",
                "probabilities": {"alice": 0.2, "bob": 0.8},
                "confidence": 0.6
            }
        },
        "usage": {"input_tokens": 12, "output_tokens": 2}
    })
    .to_string()
}

fn response(status: u16, body: &str, extra_headers: &str) -> String {
    let reason = if status == 200 { "OK" } else { "Error" };
    format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n{extra_headers}\r\n{body}",
        body.len()
    )
}

async fn server(responses: Vec<String>) -> (String, Arc<Mutex<Vec<String>>>) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let requests = Arc::new(Mutex::new(Vec::new()));
    let recorded = Arc::clone(&requests);
    tokio::spawn(async move {
        for reply in responses {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut buffer = vec![0_u8; 16_384];
            let count = stream.read(&mut buffer).await.unwrap();
            recorded
                .lock()
                .await
                .push(String::from_utf8_lossy(&buffer[..count]).into_owned());
            stream.write_all(reply.as_bytes()).await.unwrap();
        }
    });
    (format!("http://{address}"), requests)
}

async fn slow_server() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    tokio::spawn(async move {
        let (_stream, _) = listener.accept().await.unwrap();
        tokio::time::sleep(Duration::from_millis(100)).await;
    });
    format!("http://{address}")
}

fn config(base_url: String) -> ClientConfig {
    let mut config = ClientConfig::new("secret-test-key");
    config.base_url = base_url;
    config.timeout = Duration::from_secs(1);
    config.retry = RetryPolicy {
        max_retries: 0,
        initial_backoff: Duration::from_millis(1),
        max_backoff: Duration::from_millis(5),
    };
    config
}

fn unavailable_base_url() -> String {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    drop(listener);
    format!("http://{address}")
}

#[tokio::test]
async fn sends_the_documented_endpoint_and_bearer_header() {
    let (base_url, requests) = server(vec![response(
        200,
        &success(),
        "x-request-id: request-7\r\n",
    )])
    .await;
    let result = Client::new(config(base_url))
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap();
    assert_eq!(result.attempts, 1);
    assert_eq!(result.request_id.as_deref(), Some("request-7"));
    assert_eq!(result.response.usage.input_tokens, Some(12));
    let sent = requests.lock().await.join("");
    assert!(sent.starts_with("POST /v1/systemone HTTP/1.1"));
    assert!(
        sent.to_ascii_lowercase()
            .contains("authorization: bearer secret-test-key")
    );
    assert!(sent.contains("\"model\":\"jev-latest\""));
}

#[tokio::test]
async fn an_exact_endpoint_override_is_not_extended_with_a_provider_path() {
    let (base_url, requests) = server(vec![response(
        200,
        &success().replace("jev-latest", "typesafe/jev-1.13-20260917"),
        "",
    )])
    .await;
    let endpoint = format!("{base_url}/api/alpha/decisions");
    let mut config = ClientConfig::openrouter("secret-test-key").with_endpoint_url(endpoint);
    config.timeout = Duration::from_secs(1);
    config.retry.max_retries = 0;

    Client::new(config)
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap();

    assert!(
        requests
            .lock()
            .await
            .join("")
            .starts_with("POST /api/alpha/decisions HTTP/1.1")
    );
}

#[tokio::test]
async fn openrouter_uses_system_one_and_accepts_a_resolved_jev_model() {
    let (base_url, requests) = server(vec![response(
        200,
        &success().replace("jev-latest", "typesafe/jev-1.13-20260917"),
        "",
    )])
    .await;
    let mut config = ClientConfig::openrouter("secret-test-key");
    config.base_url = base_url;
    config.timeout = Duration::from_secs(1);
    config.retry.max_retries = 0;
    let result = Client::new(config)
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap();
    assert_eq!(result.response.model, "typesafe/jev-1.13-20260917");
    let sent = requests.lock().await.join("");
    assert!(sent.starts_with("POST /v1/systemone HTTP/1.1"));
}

#[tokio::test]
async fn tinyhumans_proxy_uses_the_direct_system_one_path() {
    let (base_url, requests) = server(vec![response(
        200,
        &success().replace("jev-latest", "typesafe/jev-1.13-20260917"),
        "",
    )])
    .await;
    let mut config = ClientConfig::tinyhumans_openrouter("secret-test-key");
    config.base_url = base_url;
    config.timeout = Duration::from_secs(1);
    config.retry.max_retries = 0;
    Client::new(config)
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap();
    assert!(
        requests
            .lock()
            .await
            .join("")
            .starts_with("POST /agent-integrations/openrouter/systemone HTTP/1.1")
    );
}

#[tokio::test]
async fn retries_rate_limits_and_reports_attempts() {
    let (base_url, requests) =
        server(vec![response(429, "{}", ""), response(200, &success(), "")]).await;
    let mut config = config(base_url);
    config.retry.max_retries = 1;
    let result = Client::new(config)
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap();
    assert_eq!(result.attempts, 2);
    assert_eq!(requests.lock().await.len(), 2);
}

#[tokio::test]
async fn authentication_is_terminal() {
    let (base_url, requests) = server(vec![response(401, "{}", "")]).await;
    let error = Client::new(config(base_url))
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap_err();
    assert!(matches!(error.error, Error::Authentication));
    assert_eq!(error.attempts, 1);
    assert_eq!(requests.lock().await.len(), 1);
}

#[tokio::test]
async fn malformed_success_body_is_a_decode_failure() {
    let (base_url, _) = server(vec![response(200, "not-json", "")]).await;
    let error = Client::new(config(base_url))
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap_err();
    assert!(matches!(error.error, Error::Decode { .. }));
}

#[tokio::test]
async fn debug_output_redacts_the_api_key() {
    let config = config("http://127.0.0.1:1".to_owned());
    let rendered = format!("{config:?}");
    assert!(rendered.contains("[REDACTED]"));
    assert!(!rendered.contains("secret-test-key"));
    let client = Client::new(config).unwrap();
    let rendered = format!("{client:?}");
    assert!(rendered.contains("[REDACTED]"));
    assert!(!rendered.contains("secret-test-key"));
}

#[test]
fn rejects_invalid_configuration_before_transport() {
    let mut empty = ClientConfig::new("");
    empty.base_url = "not a URL".to_owned();
    assert!(matches!(
        Client::new(empty),
        Err(Error::InvalidConfig { .. })
    ));
    let mut invalid_url = ClientConfig::new("key");
    invalid_url.base_url = "not a URL".into();
    assert!(matches!(
        Client::new(invalid_url),
        Err(Error::InvalidConfig { .. })
    ));
}

#[test]
fn validates_every_configuration_bound_and_redacted_key_replacement() {
    let replaced = ClientConfig::new("old").with_api_key("new-secret");
    let rendered = format!("{replaced:?}");
    assert!(!rendered.contains("new-secret"));
    let endpoint =
        ClientConfig::new("key").with_endpoint_url("https://example.com/custom/decisions");
    assert_eq!(
        endpoint.endpoint_url(),
        Some("https://example.com/custom/decisions")
    );
    for endpoint_url in [
        "not a URL",
        "file:///tmp/decisions",
        "http://example.com/decisions",
        "http://localhost:8080/decisions",
        "https://user:password@example.com/decisions",
        "https://example.com/decisions?tenant=x",
        "https://example.com/decisions#fragment",
    ] {
        let config = ClientConfig::new("key").with_endpoint_url(endpoint_url);
        assert!(matches!(
            Client::new(config),
            Err(Error::InvalidConfig { .. })
        ));
    }

    let mut scheme = ClientConfig::new("key");
    scheme.base_url = "file:///tmp/socket".into();
    assert!(matches!(
        Client::new(scheme),
        Err(Error::InvalidConfig { .. })
    ));

    for base_url in ["http://example.com", "http://localhost:8080"] {
        let mut cleartext = ClientConfig::new("key");
        cleartext.base_url = base_url.into();
        assert!(matches!(
            Client::new(cleartext),
            Err(Error::InvalidConfig { .. })
        ));
    }
    let mut secure = ClientConfig::new("key");
    secure.base_url = "https://example.com".into();
    assert!(Client::new(secure).is_ok());
    let openrouter = ClientConfig::openrouter("key");
    assert_eq!(openrouter.base_url, "https://openrouter.ai/api");
    assert_eq!(openrouter.provider, Provider::OpenRouter);
    let tinyhumans = ClientConfig::tinyhumans_openrouter("key");
    assert_eq!(tinyhumans.base_url, "https://api.tinyhumans.ai");
    assert_eq!(
        tinyhumans.system_one_path,
        "agent-integrations/openrouter/systemone"
    );
    assert_eq!(tinyhumans.provider, Provider::OpenRouter);
    let mut ipv6_loopback = ClientConfig::new("key");
    ipv6_loopback.base_url = "http://[::1]:8080".into();
    assert!(Client::new(ipv6_loopback).is_ok());
    let mut userinfo = ClientConfig::new("key");
    userinfo.base_url = "https://user:password@example.com".into();
    assert!(matches!(
        Client::new(userinfo),
        Err(Error::InvalidConfig { .. })
    ));
    for base_url in [
        "https://example.com?tenant=x",
        "https://example.com#fragment",
    ] {
        let mut component = ClientConfig::new("key");
        component.base_url = base_url.into();
        assert!(matches!(
            Client::new(component),
            Err(Error::InvalidConfig { .. })
        ));
    }

    let mut timeout = ClientConfig::new("key");
    timeout.timeout = Duration::ZERO;
    assert!(matches!(
        Client::new(timeout),
        Err(Error::InvalidConfig { .. })
    ));

    let mut retry = ClientConfig::new("key");
    retry.retry.initial_backoff = Duration::ZERO;
    assert!(matches!(
        Client::new(retry),
        Err(Error::InvalidConfig { .. })
    ));
    let mut unbounded = ClientConfig::new("key");
    unbounded.retry.max_retries = u32::MAX;
    assert!(matches!(
        Client::new(unbounded),
        Err(Error::InvalidConfig { .. })
    ));
}

#[test]
fn retry_delay_is_exponential_and_bounded() {
    let policy = RetryPolicy {
        max_retries: 5,
        initial_backoff: Duration::from_millis(10),
        max_backoff: Duration::from_millis(25),
    };
    assert_eq!(policy.delay(1), Duration::from_millis(10));
    assert_eq!(policy.delay(2), Duration::from_millis(20));
    assert_eq!(policy.delay(30), Duration::from_millis(25));
}

#[test]
fn status_classification_covers_terminal_and_retryable_classes() {
    assert!(matches!(
        classify_status(StatusCode::BAD_REQUEST, None),
        Failure::Terminal(Error::Unprocessable)
    ));
    assert!(matches!(
        classify_status(StatusCode::NOT_FOUND, None),
        Failure::Terminal(Error::HttpStatus { status: 404 })
    ));
    assert!(matches!(
        classify_status(StatusCode::INTERNAL_SERVER_ERROR, None),
        Failure::Retryable {
            error: Error::HttpStatus { status: 500 },
            ..
        }
    ));
    assert!(matches!(
        classify_status(StatusCode::REQUEST_TIMEOUT, None),
        Failure::Retryable {
            error: Error::Timeout,
            ..
        }
    ));
    assert!(matches!(
        classify_status(StatusCode::from_u16(529).unwrap(), None),
        Failure::Retryable {
            error: Error::Overloaded,
            ..
        }
    ));
    assert_eq!(
        parse_retry_after(Some(&reqwest::header::HeaderValue::from_static("3"))),
        Some(Duration::from_secs(3))
    );
    assert_eq!(
        parse_retry_after(Some(&reqwest::header::HeaderValue::from_static("date"))),
        None
    );
    let now = SystemTime::UNIX_EPOCH + Duration::from_secs(1_000_000);
    let future = now + Duration::from_secs(30);
    let date = httpdate::fmt_http_date(future);
    let header = reqwest::header::HeaderValue::from_str(&date).unwrap();
    assert_eq!(
        parse_retry_after_at(Some(&header), now),
        Some(Duration::from_secs(30))
    );
}

#[tokio::test]
async fn timeout_is_retryable_but_respects_the_attempt_bound() {
    let mut config = config(slow_server().await);
    config.timeout = Duration::from_millis(5);
    let error = Client::new(config)
        .unwrap()
        .evaluate(&request())
        .await
        .unwrap_err();
    assert!(matches!(error.error, Error::Timeout));
    assert_eq!(error.attempts, 1);
    assert!(error.latency >= Duration::from_millis(5));
}

